/**
 * S1 phase 2 — the payment-upload token is minted at send time and never persisted.
 *
 * Real NotificationSenderWorker + real NotificationMessageBuilder + real
 * UploadLinkBinder + real PaymentUploadTokenService; only Prisma, the payment
 * account source, the registry and the provider transport are stubbed. Tokens
 * are generated by the real service (random, per run) and never printed.
 */
import { NotificationChannel } from '@prisma/client';
import { NotificationSenderWorker } from '../../src/infrastructure/notifications/notification-sender.worker';
import { NotificationMessageBuilder } from '../../src/infrastructure/notifications/notification-message.builder';
import { UploadLinkBinder } from '../../src/infrastructure/notifications/upload-link.binder';
import { PaymentUploadTokenService } from '../../src/modules/payments/payment-upload-token.service';
import { NotificationBlockedError } from '../../src/infrastructure/notifications/notification-delivery.gate';
import { TransientSendError } from '../../src/infrastructure/notifications/notification-provider';
import { ConfigurationError } from '../../src/common/errors/configuration.error';
import { NotificationMessage } from '../../src/infrastructure/notifications/notification-message';

const ACCOUNT = { bankName: 'BCA', bankCode: '014', accountName: 'Toko', accountNumber: '1234567890' };

function transferRow(over: Record<string, unknown> = {}) {
  return {
    id: 'ntf-1', channel: NotificationChannel.WHATSAPP, recipient: '6281234567890', template: 'order.transfer',
    payload: { orderId: 'order-1', paymentId: 'pay-1', orderNumber: 'BMS-1', totalPrice: 135123, customerName: 'Jane', customerPhone: '6281234567890', paymentMethod: 'BANK_TRANSFER' },
    status: 'PENDING', attempts: 0, nextAttemptAt: new Date(0), lockedUntil: null, lockedBy: 'w#1',
    providerMessageId: null, lastError: null, sourceMessageId: 'evt-1', createdAt: new Date(0), sentAt: null,
    ...over,
  };
}

function harness(opts: { rows?: ReturnType<typeof transferRow>[]; gateBlocks?: boolean; send?: jest.Mock; paymentByOrder?: string | null; wireBinder?: boolean } = {}) {
  const rows = opts.rows ?? [transferRow()];
  const tokenRows: Array<{ token: string; paymentId: string }> = [];
  const prisma = {
    $executeRawUnsafe: jest.fn().mockResolvedValue(1),
    notificationOutbox: {
      findMany: jest.fn().mockResolvedValue(rows),
      updateMany: jest.fn().mockResolvedValue({ count: 1 }),
      count: jest.fn().mockResolvedValue(0),
      findFirst: jest.fn().mockResolvedValue(null),
    },
    paymentUploadToken: {
      create: jest.fn().mockImplementation(({ data }: { data: { token: string; paymentId: string } }) => {
        tokenRows.push({ token: data.token, paymentId: data.paymentId });
        return Promise.resolve({});
      }),
      updateMany: jest.fn(),
      deleteMany: jest.fn(),
    },
    payment: {
      findUnique: jest.fn().mockImplementation(() =>
        Promise.resolve(opts.paymentByOrder === null ? null : { id: opts.paymentByOrder ?? 'pay-from-order' }),
      ),
    },
  };
  const tokens = new PaymentUploadTokenService(prisma as never);
  const binder = new UploadLinkBinder(prisma as never, tokens);
  const registry = { resolve: jest.fn().mockReturnValue({ providerTemplateId: 'tpl-invoice', body: [], button: true }) };
  const builder = new NotificationMessageBuilder({ getActiveAccount: jest.fn().mockResolvedValue(ACCOUNT) } as never, registry as never);
  const sent: NotificationMessage[] = [];
  const send = opts.send ?? jest.fn().mockResolvedValue({ providerMessageId: 'pm-1' });
  const provider = { channel: 'WHATSAPP', send: jest.fn((m: NotificationMessage) => { sent.push(m); return send(m); }) };
  const factory = { get: jest.fn().mockReturnValue(provider) };
  const gate = {
    assertDeliverable: jest.fn(() => {
      if (opts.gateBlocks) throw new NotificationBlockedError('delivery disabled');
    }),
  };
  const metrics = {
    claimed: jest.fn(), sent: jest.fn(), retried: jest.fn(), failedPermanent: jest.fn(),
    failedExhausted: jest.fn(), senderPaused: jest.fn(), senderResumed: jest.fn(), health: jest.fn(),
  };
  const config = {
    enabled: true, batchSize: 50, leaseMs: 30_000, pollIntervalMs: 1_000, backoffBaseMs: 1_000, backoffCapMs: 100_000,
    maxAttempts: 8, healthLogIntervalMs: 60_000, breakerThreshold: 99, pauseMs: 30_000,
    emailApiKey: 'k', emailFrom: 'f@x.test', emailRequestTimeoutMs: 10_000,
  };
  const worker = new NotificationSenderWorker(
    prisma as never, builder, factory as never, metrics as never, config, gate as never, undefined,
    opts.wireBinder === false ? undefined : binder,
  );
  return { worker, prisma, tokens, sent, tokenRows, provider, gate, metrics };
}

/** Everything the sender persisted for a row (fenced write-backs). */
const writes = (h: ReturnType<typeof harness>) => JSON.stringify(h.prisma.notificationOutbox.updateMany.mock.calls);
const tokenOf = (m: NotificationMessage) => (m.variables as { uploadToken?: string }).uploadToken ?? '';

describe('S1: the builder never reads or produces an upload token', () => {
  it('order.transfer leaves uploadToken empty and asks for a link for the row payment', async () => {
    const h = harness();
    const msg = await new NotificationMessageBuilder({ getActiveAccount: jest.fn().mockResolvedValue(ACCOUNT) } as never, { resolve: () => ({ providerTemplateId: 't' }) } as never).build(transferRow() as never);
    expect(tokenOf(msg)).toBe('');
    expect(msg.uploadLinkFor).toEqual({ paymentId: 'pay-1', orderId: 'order-1' });
    expect(h.tokenRows).toHaveLength(0);
  });

  it('ignores a legacy uploadToken stored on a pre-S1 row', async () => {
    const legacy = 'c'.repeat(64);
    const msg = await new NotificationMessageBuilder({ getActiveAccount: jest.fn().mockResolvedValue(ACCOUNT) } as never, { resolve: () => ({ providerTemplateId: 't' }) } as never)
      .build(transferRow({ payload: { orderId: 'order-1', orderNumber: 'BMS-1', totalPrice: 1, uploadToken: legacy } }) as never);
    expect(JSON.stringify(msg)).not.toContain(legacy);
    expect(msg.uploadLinkFor).toEqual({ orderId: 'order-1' });
  });

  it('a transfer row with neither paymentId nor orderId fails permanently (never sent link-less)', async () => {
    const builder = new NotificationMessageBuilder({ getActiveAccount: jest.fn().mockResolvedValue(ACCOUNT) } as never, { resolve: () => ({ providerTemplateId: 't' }) } as never);
    await expect(builder.build(transferRow({ payload: { orderNumber: 'BMS-1' } }) as never)).rejects.toBeInstanceOf(ConfigurationError);
  });

  it('non-transfer templates carry no upload-link request', async () => {
    const builder = new NotificationMessageBuilder({ getActiveAccount: jest.fn() } as never, { resolve: () => ({ providerTemplateId: 't' }) } as never);
    const msg = await builder.build(transferRow({ template: 'order.cod', payload: { orderId: 'order-1', orderNumber: 'BMS-1', totalPrice: 1 } }) as never);
    expect(msg.uploadLinkFor).toBeUndefined();
  });
});

describe('S1: UploadLinkBinder mints at send time and stores only the hash', () => {
  it('binds a fresh 256-bit token to the in-memory message; only its SHA-256 is written', async () => {
    const h = harness();
    await h.worker.sendRow(transferRow() as never);
    expect(h.sent).toHaveLength(1);
    const raw = tokenOf(h.sent[0]);
    expect(raw).toMatch(/^[0-9a-f]{64}$/);
    expect(h.tokenRows).toEqual([{ token: h.tokens.hash(raw), paymentId: 'pay-1' }]);
    expect(h.tokenRows[0].token).not.toBe(raw);
    // Never written back to the outbox row.
    expect(writes(h)).not.toContain(raw);
    expect(writes(h)).not.toMatch(/uploadToken|uploadUrl|payload/);
    expect(h.metrics.sent).toHaveBeenCalled();
  });

  it('pre-S1 rows (orderId only) resolve the payment through Payment.orderId', async () => {
    const h = harness({ paymentByOrder: 'pay-legacy' });
    await h.worker.sendRow(transferRow({ payload: { orderId: 'order-9', orderNumber: 'BMS-9', totalPrice: 1, uploadToken: 'd'.repeat(64) } }) as never);
    expect(h.prisma.payment.findUnique).toHaveBeenCalledWith({ where: { orderId: 'order-9' }, select: { id: true } });
    expect(h.tokenRows).toEqual([{ token: expect.any(String), paymentId: 'pay-legacy' }]);
    expect(tokenOf(h.sent[0])).not.toBe('d'.repeat(64)); // the stored legacy token is not reused
  });

  it('no payment for the row → permanent FAILED, nothing minted, nothing sent', async () => {
    const h = harness({ paymentByOrder: null });
    await h.worker.sendRow(transferRow({ payload: { orderId: 'order-x', orderNumber: 'BMS-X', totalPrice: 1 } }) as never);
    expect(h.provider.send).not.toHaveBeenCalled();
    expect(h.tokenRows).toHaveLength(0);
    expect(h.metrics.failedPermanent).toHaveBeenCalled();
  });
});

describe('S1: send-time ordering, retries and failure semantics', () => {
  it('a row blocked by the delivery gate mints NO token', async () => {
    const h = harness({ gateBlocks: true });
    await h.worker.sendRow(transferRow() as never);
    expect(h.tokenRows).toHaveLength(0);
    expect(h.provider.send).not.toHaveBeenCalled();
    expect(h.metrics.failedPermanent).toHaveBeenCalled();
  });

  it('a transient provider failure (possibly delivered) keeps that token valid; the retry mints a second, both stay active', async () => {
    const send = jest.fn()
      .mockRejectedValueOnce(new TransientSendError('timeout after send'))
      .mockResolvedValueOnce({ providerMessageId: 'pm-2' });
    const h = harness({ send });
    await h.worker.sendRow(transferRow() as never); // attempt 1: timeout → retry scheduled
    await h.worker.sendRow(transferRow({ attempts: 1 }) as never); // attempt 2: delivered
    expect(h.tokenRows).toHaveLength(2);
    const [first, second] = h.sent.map(tokenOf);
    expect(first).not.toBe(second);
    // Nothing revokes or expires the first token: no update/delete on PaymentUploadToken.
    expect(h.prisma.paymentUploadToken.updateMany).not.toHaveBeenCalled();
    expect(h.prisma.paymentUploadToken.deleteMany).not.toHaveBeenCalled();
    // Same provider idempotency key on both attempts (provider-side dedup still applies).
    expect(h.sent[0].metadata.idempotencyKey).toBe(h.sent[1].metadata.idempotencyKey);
    // The retry write-back carries the error only — never a token.
    expect(writes(h)).not.toContain(first);
    expect(writes(h)).not.toContain(second);
  });

  it('a message that needs a link but has no binder wired fails CLOSED (never sent without the button)', async () => {
    const h = harness({ wireBinder: false });
    await h.worker.sendRow(transferRow() as never);
    expect(h.provider.send).not.toHaveBeenCalled();
    expect(h.metrics.failedPermanent).toHaveBeenCalled();
  });

  it('messages without an upload link never touch the binder', async () => {
    const h = harness();
    await h.worker.sendRow(transferRow({ template: 'order.cod', payload: { orderId: 'order-1', orderNumber: 'BMS-1', totalPrice: 1 } }) as never);
    expect(h.tokenRows).toHaveLength(0);
    expect(h.provider.send).toHaveBeenCalledTimes(1);
  });
});
